     1→/**
     2→ * FreeLang Nexus - 코드 생성기
     3→ * AST → C 코드 (V 모드) + Python 코드 (Python 모드)
     4→ */
     5→
     6→import * as AST from '../parser/ast';
     7→
     8→export interface CodegenResult {
     9→  c: string;       // V 모드 함수들 → C 코드
    10→  python: string;  // Python 모드 함수들 → Python 코드
    11→  mixed: string;   // 두 코드 주석으로 구분 (디버그용)
    12→}
    13→
    14→export class NexusCodegen {
    15→  private cLines: string[] = [];
    16→  private pyLines: string[] = [];
    17→  private indentLevel: number = 0;
    18→
    19→  /**
    20→   * V 모드 내장 함수 처리
    21→   */
    22→  private readonly V_BUILTINS = new Set(['println', 'print', 'len', 'to_string']);
    23→
    24→  /**
    25→   * 프로그램 전체 코드 생성
    26→   */
    27→  generate(program: AST.Program): CodegenResult {
    28→    // @mode 마커는 무시하고 함수/문장만 처리
    29→    for (const item of program.body) {
    30→      const fnItem = item as any;
    31→      if (fnItem.type === 'VFunction') {
    32→        this.genVFunction(fnItem as AST.VFunction);
    33→      } else if (fnItem.type === 'PyFunction') {
    34→        this.genPyFunction(fnItem as AST.PyFunction);
    35→      } else if (fnItem.type === 'Return' || fnItem.type === 'Assign' || fnItem.type === 'ExprStatement') {
    36→        // 탑레벨 문장은 V 모드(C)로 처리
    37→        this.genVStatement(fnItem as AST.Statement);
    38→      }
    39→    }
    40→
    41→    const c = this.cLines.join('\n');
    42→    const python = this.pyLines.join('\n');
    43→
    44→    // mixed: 두 언어 코드를 주석으로 구분해서 출력 (확인용)
    45→    const mixed =
    46→      c && python
    47→        ? `/* ===== V (C) ===== */\n${c}\n\n/* ===== Python ===== */\n# (Not valid C, just for reference)\n${python}`
    48→        : c || python;
    49→
    50→    return { c, python, mixed };
    51→  }
    52→
    53→  /**
    54→   * 실행 가능한 프로그램 생성
    55→   * C에는 #include + main() 추가, Python에는 if __name__ 추가
    56→   */
    57→  generateProgram(program: AST.Program): CodegenResult {
    58→    const base = this.generate(program);
    59→
    60→    // C 코드에 헤더 + main() wrapping 추가
    61→    const cWithMain = base.c
    62→      ? `#include <stdio.h>\n#include <stdbool.h>\n#include <string.h>\n\n${base.c}\nint main() {\n    return 0;\n}\n`
    63→      : '';
    64→
    65→    // Python 코드에 main 블록 추가
    66→    const pyWithMain = base.python
    67→      ? `${base.python}\n\nif __name__ == '__main__':\n    pass\n`
    68→      : '';
    69→
    70→    return {
    71→      c: cWithMain,
    72→      python: pyWithMain,
    73→      mixed: base.mixed,
    74→    };
    75→  }
    76→
    77→  /**
    78→   * V 함수 → C 함수
    79→   * fn add(x: i64, y: i64) -> i64 { return x + y }
    80→   * →
    81→   * long long add(long long x, long long y) { return x + y; }
    82→   */
    83→  private genVFunction(fn: AST.VFunction): void {
    84→    // 반환타입
    85→    const returnType = this.mapVType(fn.returnType || 'void');
    86→
    87→    // 파라미터 리스트
    88→    const paramList = fn.params.map((p) => `${this.mapVType(p.typeAnnotation || 'void')} ${p.name}`).join(', ');
    89→
    90→    // 함수 시그니처
    91→    this.writeC(`${returnType} ${fn.name}(${paramList}) {`);
    92→
    93→    // 함수 본문
    94→    this.indentLevel++;
    95→    for (const stmt of fn.body) {
    96→      this.genVStatement(stmt);
    97→    }
    98→    this.indentLevel--;
    99→
   100→    this.writeC('}');
   101→    this.writeC(''); // 빈 줄
   102→  }
   103→
   104→  /**
   105→   * Python 함수 → Python 함수
   106→   * def slow(items): return items
   107→   * →
   108→   * def slow(items):
   109→   *     return items
   110→   */
   111→  private genPyFunction(fn: AST.PyFunction): void {
   112→    // 파라미터 리스트
   113→    const paramList = fn.params.map((p) => p.name).join(', ');
   114→
   115→    // 함수 정의
   116→    this.writePy(`def ${fn.name}(${paramList}):`);
   117→
   118→    // 함수 본문 (들여쓰기 필요)
   119→    this.indentLevel++;
   120→    for (const stmt of fn.body) {
   121→      this.genPyStatement(stmt);
   122→    }
   123→    this.indentLevel--;
   124→
   125→    this.writePy(''); // 빈 줄
   126→  }
   127→
   128→  /**
   129→   * V 문장 생성 (C 코드용)
   130→   */
   131→  private genVStatement(stmt: AST.Statement): void {
   132→    const s = stmt as any;
   133→
   134→    if (s.type === 'Return') {
   135→      const returnStmt = s as AST.ReturnStatement;
   136→      if (returnStmt.value) {
   137→        const expr = this.genVExpression(returnStmt.value);
   138→        this.writeC(`${this.indent()}return ${expr};`);
   139→      } else {
   140→        this.writeC(`${this.indent()}return;`);
   141→      }
   142→    } else if (s.type === 'Assign') {
   143→      const assignStmt = s as AST.AssignStatement;
   144→      const expr = this.genVExpression(assignStmt.value);
   145→      // C에서는 타입을 추론할 수 없으므로 기본값으로 long long 사용
   146→      this.writeC(`${this.indent()}long long ${assignStmt.name} = ${expr};`);
   147→    } else if (s.type === 'ExprStatement') {
   148→      const exprStmt = s as AST.ExprStatement;
   149→      const expr = this.genVExpression(exprStmt.expression);
   150→      this.writeC(`${this.indent()}${expr};`);
   151→    }
   152→  }
   153→
   154→  /**
   155→   * Python 문장 생성 (Python 코드용)
   156→   */
   157→  private genPyStatement(stmt: AST.Statement): void {
   158→    const s = stmt as any;
   159→    const indentStr = this.indent();
   160→
   161→    if (s.type === 'Return') {
   162→      const returnStmt = s as AST.ReturnStatement;
   163→      if (returnStmt.value) {
   164→        const expr = this.genPyExpression(returnStmt.value);
   165→        this.writePy(`${indentStr}return ${expr}`);
   166→      } else {
   167→        this.writePy(`${indentStr}return`);
   168→      }
   169→    } else if (s.type === 'Assign') {
   170→      const assignStmt = s as AST.AssignStatement;
   171→      const expr = this.genPyExpression(assignStmt.value);
   172→      this.writePy(`${indentStr}${assignStmt.name} = ${expr}`);
   173→    } else if (s.type === 'ExprStatement') {
   174→      const exprStmt = s as AST.ExprStatement;
   175→      const expr = this.genPyExpression(exprStmt.expression);
   176→      this.writePy(`${indentStr}${expr}`);
   177→    }
   178→  }
   179→
   180→  /**
   181→   * V 표현식 생성 (C 코드용)
   182→   */
   183→  private genVExpression(expr: AST.Expression): string {
   184→    const e = expr as any;
   185→
   186→    if (e.type === 'Number') {
   187→      return (e as AST.NumberLiteral).value.toString();
   188→    }
   189→
   190→    if (e.type === 'String') {
   191→      return `"${(e as AST.StringLiteral).value}"`;
   192→    }
   193→
   194→    if (e.type === 'Identifier') {
   195→      return (e as AST.Identifier).name;
   196→    }
   197→
   198→    if (e.type === 'BinaryExpr') {
   199→      const binExpr = e as AST.BinaryExpr;
   200→      const left = this.genVExpression(binExpr.left);
   201→      const right = this.genVExpression(binExpr.right);
   202→      return `${left} ${binExpr.operator} ${right}`;
   203→    }
   204→
   205→    if (e.type === 'Call') {
   206→      const callExpr = e as AST.CallExpr;
   207→
   208→      // callee가 Identifier인 경우 함수명 추출
   209→      let calleeStr: string | null = null;
   210→      if (typeof callExpr.callee === 'string') {
   211→        calleeStr = callExpr.callee;
   212→      } else {
   213→        const calleeExpr = callExpr.callee as any;
   214→        if (calleeExpr.type === 'Identifier') {
   215→          calleeStr = calleeExpr.name;
   216→        }
   217→      }
   218→
   219→      // V 내장 함수 처리
   220→      if (calleeStr && this.V_BUILTINS.has(calleeStr)) {
   221→        return this.genVBuiltinCall(calleeStr, callExpr.args);
   222→      }
   223→
   224→      // 일반 함수 호출
   225→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genVExpression(callExpr.callee);
   226→      const args = callExpr.args.map((arg) => this.genVExpression(arg)).join(', ');
   227→      return `${callee}(${args})`;
   228→    }
   229→
   230→    return '';
   231→  }
   232→
   233→  /**
   234→   * V 모드 내장 함수 호출 생성
   235→   */
   236→  private genVBuiltinCall(name: string, args: AST.Expression[]): string {
   237→    if (name === 'println') {
   238→      if (args.length === 0) return 'printf("\\n")';
   239→      const firstArg = args[0] as any;
   240→      // StringLiteral인 경우: printf의 format string으로 사용
   241→      if (firstArg.type === 'String') {
   242→        // firstArg.value는 "text" 형태이므로 따옴표 제거
   243→        const str = firstArg.value.slice(1, -1);
   244→        return `printf("${str}\\n")`;
   245→      }
   246→      // 숫자/식별자인 경우 %lld 포맷 사용
   247→      const arg = this.genVExpression(firstArg);
   248→      return `printf("%lld\\n", ${arg})`;
   249→    }
   250→
   251→    if (name === 'print') {
   252→      if (args.length === 0) return 'printf("")';
   253→      const firstArg = args[0] as any;
   254→      if (firstArg.type === 'String') {
   255→        // StringLiteral인 경우: printf의 format string으로 사용
   256→        const str = firstArg.value.slice(1, -1);
   257→        return `printf("${str}")`;
   258→      }
   259→      const arg = this.genVExpression(firstArg);
   260→      return `printf("%lld", ${arg})`;
   261→    }
   262→
   263→    if (name === 'len') {
   264→      const firstArg = args[0] as any;
   265→      if (firstArg.type === 'String') {
   266→        // StringLiteral인 경우 따옴표 제거
   267→        const str = firstArg.value.slice(1, -1);
   268→        return `strlen("${str}")`;
   269→      }
   270→      const arg = this.genVExpression(firstArg);
   271→      return `strlen(${arg})`;
   272→    }
   273→
   274→    if (name === 'to_string') {
   275→      const arg = this.genVExpression(args[0]);
   276→      return arg; // 단순 pass-through
   277→    }
   278→
   279→    return '';
   280→  }
   281→
   282→  /**
   283→   * Python 표현식 생성 (Python 코드용)
   284→   */
   285→  private genPyExpression(expr: AST.Expression): string {
   286→    const e = expr as any;
   287→
   288→    if (e.type === 'Number') {
   289→      return (e as AST.NumberLiteral).value.toString();
   290→    }
   291→
   292→    if (e.type === 'String') {
   293→      return `"${(e as AST.StringLiteral).value}"`;
   294→    }
   295→
   296→    if (e.type === 'Identifier') {
   297→      return (e as AST.Identifier).name;
   298→    }
   299→
   300→    if (e.type === 'BinaryExpr') {
   301→      const binExpr = e as AST.BinaryExpr;
   302→      const left = this.genPyExpression(binExpr.left);
   303→      const right = this.genPyExpression(binExpr.right);
   304→      return `${left} ${binExpr.operator} ${right}`;
   305→    }
   306→
   307→    if (e.type === 'Call') {
   308→      const callExpr = e as AST.CallExpr;
   309→      const callee = typeof callExpr.callee === 'string' ? callExpr.callee : this.genPyExpression(callExpr.callee);
   310→      const args = callExpr.args.map((arg) => this.genPyExpression(arg)).join(', ');
   311→      return `${callee}(${args})`;
   312→    }
   313→
   314→    return '';
   315→  }
   316→
   317→  /**
   318→   * V 타입 → C 타입 매핑
   319→   */
   320→  private mapVType(type: string): string {
   321→    const mapping: Record<string, string> = {
   322→      i64: 'long long',
   323→      i32: 'int',
   324→      f64: 'double',
   325→      f32: 'float',
   326→      bool: 'bool',
   327→      string: 'char*',
   328→      void: 'void',
   329→    };
   330→
   331→    return mapping[type] || type;
   332→  }
   333→
   334→  /**
   335→   * Python 타입 → Python 타입 (기본값)
   336→   */
   337→  private mapPyType(type: string): string {
   338→    const mapping: Record<string, string> = {
   339→      i64: 'int',
   340→      i32: 'int',
   341→      f64: 'float',
   342→      f32: 'float',
   343→      bool: 'bool',
   344→      string: 'str',
   345→      void: 'None',
   346→      int: 'int',
   347→      float: 'float',
   348→    };
   349→
   350→    return mapping[type] || type;
   351→  }
   352→
   353→  /**
   354→   * C 코드에 줄 추가
   355→   */
   356→  private writeC(line: string): void {
   357→    this.cLines.push(line);
   358→  }
   359→
   360→  /**
   361→   * Python 코드에 줄 추가
   362→   */
   363→  private writePy(line: string): void {
   364→    this.pyLines.push(line);
   365→  }
   366→
   367→  /**
   368→   * 현재 들여쓰기 문자열
   369→   */
   370→  private indent(): string {
   371→    return '    '.repeat(this.indentLevel);
   372→  }
   373→}
   374→

