     1→/**
     2→ * FreeLang Nexus - AST 노드 정의
     3→ * V 모드 함수와 Python 모드 함수 통합 AST
     4→ */
     5→
     6→/**
     7→ * 모든 AST 노드의 기본 인터페이스
     8→ */
     9→export interface ASTNode {
    10→  type: string;
    11→  line: number;
    12→  column: number;
    13→  mode: 'v' | 'python' | 'auto';
    14→}
    15→
    16→/**
    17→ * 파라미터 정의
    18→ */
    19→export interface Parameter {
    20→  name: string;
    21→  typeAnnotation?: string; // i64, string 등 (선택)
    22→  line: number;
    23→  column: number;
    24→}
    25→
    26→/**
    27→ * V 모드 함수
    28→ * 예: fn add(x: i64, y: i64) -> i64 { return x + y }
    29→ */
    30→export interface VFunction extends ASTNode {
    31→  type: 'VFunction';
    32→  name: string;
    33→  params: Parameter[];
    34→  returnType?: string; // -> 타입
    35→  body: Statement[];
    36→  mode: 'v';
    37→}
    38→
    39→/**
    40→ * Python 모드 함수
    41→ * 예: def add(a, b): return a + b
    42→ */
    43→export interface PyFunction extends ASTNode {
    44→  type: 'PyFunction';
    45→  name: string;
    46→  params: Parameter[];
    47→  returnType?: string; // -> 타입 (선택)
    48→  body: Statement[];
    49→  mode: 'python';
    50→}
    51→
    52→/**
    53→ * Return 문장
    54→ */
    55→export interface ReturnStatement extends ASTNode {
    56→  type: 'Return';
    57→  value?: Expression;
    58→}
    59→
    60→/**
    61→ * 할당 문장
    62→ */
    63→export interface AssignStatement extends ASTNode {
    64→  type: 'Assign';
    65→  name: string;
    66→  value: Expression;
    67→}
    68→
    69→/**
    70→ * 표현식 문장
    71→ */
    72→export interface ExprStatement extends ASTNode {
    73→  type: 'ExprStatement';
    74→  expression: Expression;
    75→}
    76→
    77→/**
    78→ * 문장 타입 (Return, Assign, ExprStatement)
    79→ */
    80→export type Statement = ReturnStatement | AssignStatement | ExprStatement;
    81→
    82→/**
    83→ * 숫자 리터럴
    84→ */
    85→export interface NumberLiteral extends ASTNode {
    86→  type: 'Number';
    87→  value: number | string; // 16진수, 이진수 표현 가능
    88→}
    89→
    90→/**
    91→ * 문자열 리터럴
    92→ */
    93→export interface StringLiteral extends ASTNode {
    94→  type: 'String';
    95→  value: string;
    96→}
    97→
    98→/**
    99→ * 식별자 (변수명, 함수명 등)
   100→ */
   101→export interface Identifier extends ASTNode {
   102→  type: 'Identifier';
   103→  name: string;
   104→}
   105→
   106→/**
   107→ * 이항 연산식
   108→ * 예: x + y, a * b
   109→ */
   110→export interface BinaryExpr extends ASTNode {
   111→  type: 'BinaryExpr';
   112→  left: Expression;
   113→  operator: string; // +, -, *, /, &&, ||, ==, !=, <, >, <=, >=
   114→  right: Expression;
   115→}
   116→
   117→/**
   118→ * 함수 호출 표현식
   119→ * 예: foo(), Module::func()
   120→ */
   121→export interface CallExpr extends ASTNode {
   122→  type: 'Call';
   123→  callee: Expression | string; // Identifier 또는 Module::func 형식 문자열
   124→  args: Expression[];
   125→}
   126→
   127→/**
   128→ * 표현식 타입
   129→ */
   130→export type Expression = NumberLiteral | StringLiteral | Identifier | BinaryExpr | CallExpr;
   131→
   132→/**
   133→ * 프로그램 (최상위 노드)
   134→ */
   135→export interface Program {
   136→  type: 'Program';
   137→  body: Array<VFunction | PyFunction | Statement>;
   138→}
   139→

