     1→/**
     2→ * FreeLang Nexus - 통합 Parser
     3→ * V 모드 + Python 모드 함수를 혼합하여 파싱
     4→ */
     5→
     6→import { Token, TokenType } from '../lexer/token';
     7→import * as AST from './ast';
     8→
     9→export class NexusParser {
    10→  private tokens: Token[];
    11→  private pos: number = 0;
    12→
    13→  constructor(tokens: Token[]) {
    14→    this.tokens = tokens;
    15→  }
    16→
    17→  /**
    18→   * 파싱 진입점
    19→   */
    20→  parse(): AST.Program {
    21→    const body: Array<AST.VFunction | AST.PyFunction | AST.Statement> = [];
    22→
    23→    while (!this.isAtEnd()) {
    24→      this.skipNewlines();
    25→      if (this.isAtEnd()) break;
    26→
    27→      const token = this.peek();
    28→
    29→      // @mode 마커는 스킵 (이미 렉서에서 처리됨)
    30→      if (token.type === TokenType.MODE_MARKER) {
    31→        this.advance();
    32→        continue;
    33→      }
    34→
    35→      // 탑레벨 아이템 파싱
    36→      const item = this.parseTopLevel();
    37→      if (item) {
    38→        body.push(item);
    39→      }
    40→    }
    41→
    42→    return { type: 'Program', body };
    43→  }
    44→
    45→  /**
    46→   * 탑레벨 아이템 파싱
    47→   * V 함수, Python 함수, 또는 문장
    48→   */
    49→  private parseTopLevel(): AST.VFunction | AST.PyFunction | AST.Statement | null {
    50→    const token = this.peek();
    51→
    52→    // V 모드 함수
    53→    if (token.type === TokenType.FN) {
    54→      return this.parseVFunction();
    55→    }
    56→
    57→    // Python 모드 함수
    58→    if (token.type === TokenType.DEF) {
    59→      return this.parsePyFunction();
    60→    }
    61→
    62→    // 그 외: 문장
    63→    return this.parseStatement();
    64→  }
    65→
    66→  /**
    67→   * V 함수 파싱
    68→   * fn name(params) -> type { body }
    69→   */
    70→  private parseVFunction(): AST.VFunction {
    71→    const startToken = this.consume(TokenType.FN, 'fn 키워드 필요');
    72→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
    73→    const name = nameToken.value;
    74→
    75→    this.consume(TokenType.LPAREN, '( 필요');
    76→    const params = this.parseVParams();
    77→    this.consume(TokenType.RPAREN, ') 필요');
    78→
    79→    const returnType = this.parseReturnType();
    80→
    81→    this.consume(TokenType.LBRACE, '{ 필요');
    82→    const body = this.parseVBlock();
    83→    this.consume(TokenType.RBRACE, '} 필요');
    84→
    85→    return {
    86→      type: 'VFunction',
    87→      name,
    88→      params,
    89→      returnType,
    90→      body,
    91→      mode: 'v',
    92→      line: startToken.line,
    93→      column: startToken.column,
    94→    };
    95→  }
    96→
    97→  /**
    98→   * Python 함수 파싱
    99→   * def name(params): INDENT body DEDENT
   100→   */
   101→  private parsePyFunction(): AST.PyFunction {
   102→    const startToken = this.consume(TokenType.DEF, 'def 키워드 필요');
   103→    const nameToken = this.consume(TokenType.IDENTIFIER, '함수명 필요');
   104→    const name = nameToken.value;
   105→
   106→    this.consume(TokenType.LPAREN, '( 필요');
   107→    const params = this.parsePyParams();
   108→    this.consume(TokenType.RPAREN, ') 필요');
   109→
   110→    const returnType = this.parseReturnType();
   111→
   112→    this.consume(TokenType.COLON, ': 필요');
   113→    this.skipNewlines();
   114→
   115→    const body = this.parsePyBlock();
   116→
   117→    return {
   118→      type: 'PyFunction',
   119→      name,
   120→      params,
   121→      returnType,
   122→      body,
   123→      mode: 'python',
   124→      line: startToken.line,
   125→      column: startToken.column,
   126→    };
   127→  }
   128→
   129→  /**
   130→   * V 함수 파라미터 파싱
   131→   * (x: i64, y: i64)
   132→   */
   133→  private parseVParams(): AST.Parameter[] {
   134→    const params: AST.Parameter[] = [];
   135→
   136→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   137→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   138→      this.consume(TokenType.COLON, ': 필요');
   139→      const typeToken = this.peek();
   140→      const typeAnnotation = this.parseType();
   141→
   142→      params.push({
   143→        name: nameToken.value,
   144→        typeAnnotation,
   145→        line: nameToken.line,
   146→        column: nameToken.column,
   147→      });
   148→
   149→      if (!this.check(TokenType.RPAREN)) {
   150→        this.consume(TokenType.COMMA, ', 필요');
   151→      }
   152→    }
   153→
   154→    return params;
   155→  }
   156→
   157→  /**
   158→   * Python 함수 파라미터 파싱
   159→   * (x, y) 또는 (x: int, y: int)
   160→   */
   161→  private parsePyParams(): AST.Parameter[] {
   162→    const params: AST.Parameter[] = [];
   163→
   164→    while (!this.check(TokenType.RPAREN) && !this.isAtEnd()) {
   165→      const nameToken = this.consume(TokenType.IDENTIFIER, '파라미터명 필요');
   166→      let typeAnnotation: string | undefined;
   167→
   168→      // 타입 어노테이션 (선택)
   169→      if (this.check(TokenType.COLON)) {
   170→        this.advance();
   171→        typeAnnotation = this.parseType();
   172→      }
   173→
   174→      params.push({
   175→        name: nameToken.value,
   176→        typeAnnotation,
   177→        line: nameToken.line,
   178→        column: nameToken.column,
   179→      });
   180→
   181→      if (!this.check(TokenType.RPAREN)) {
   182→        this.consume(TokenType.COMMA, ', 필요');
   183→      }
   184→    }
   185→
   186→    return params;
   187→  }
   188→
   189→  /**
   190→   * 반환 타입 파싱
   191→   * -> i64 (선택)
   192→   */
   193→  private parseReturnType(): string | undefined {
   194→    if (this.match(TokenType.ARROW)) {
   195→      return this.parseType();
   196→    }
   197→    return undefined;
   198→  }
   199→
   200→  /**
   201→   * 타입 파싱
   202→   * i64, string, bool 등
   203→   */
   204→  private parseType(): string {
   205→    const token = this.peek();
   206→
   207→    // 기본 타입
   208→    if (
   209→      token.type === TokenType.I64 ||
   210→      token.type === TokenType.I32 ||
   211→      token.type === TokenType.F64 ||
   212→      token.type === TokenType.BOOL ||
   213→      token.type === TokenType.STRING ||
   214→      token.type === TokenType.IDENTIFIER
   215→    ) {
   216→      return this.advance().value;
   217→    }
   218→
   219→    throw new Error(`타입 필요 at line ${token.line}`);
   220→  }
   221→
   222→  /**
   223→   * V 블록 파싱
   224→   * { statements }
   225→   */
   226→  private parseVBlock(): AST.Statement[] {
   227→    const statements: AST.Statement[] = [];
   228→
   229→    while (!this.check(TokenType.RBRACE) && !this.isAtEnd()) {
   230→      this.skipNewlines();
   231→
   232→      if (this.check(TokenType.RBRACE)) break;
   233→
   234→      const stmt = this.parseStatement();
   235→      if (stmt) {
   236→        statements.push(stmt);
   237→      }
   238→
   239→      this.skipNewlines();
   240→    }
   241→
   242→    return statements;
   243→  }
   244→
   245→  /**
   246→   * Python 블록 파싱
   247→   * INDENT statements DEDENT
   248→   */
   249→  private parsePyBlock(): AST.Statement[] {
   250→    const statements: AST.Statement[] = [];
   251→
   252→    this.consume(TokenType.INDENT, 'INDENT 필요');
   253→
   254→    while (!this.check(TokenType.DEDENT) && !this.isAtEnd()) {
   255→      this.skipNewlines();
   256→
   257→      if (this.check(TokenType.DEDENT) || this.isAtEnd()) break;
   258→
   259→      const stmt = this.parseStatement();
   260→      if (stmt) {
   261→        statements.push(stmt);
   262→      }
   263→
   264→      this.skipNewlines();
   265→    }
   266→
   267→    // DEDENT 또는 EOF 모두 허용 (파일 끝에서 DEDENT가 항상 생성되지 않을 수 있음)
   268→    if (this.check(TokenType.DEDENT)) {
   269→      this.advance();
   270→    }
   271→
   272→    return statements;
   273→  }
   274→
   275→  /**
   276→   * 문장 파싱
   277→   */
   278→  private parseStatement(): AST.Statement {
   279→    const token = this.peek();
   280→
   281→    // return 문장
   282→    if (token.type === TokenType.RETURN) {
   283→      return this.parseReturnStatement();
   284→    }
   285→
   286→    // pass 문장 (Python)
   287→    if (token.type === TokenType.PASS) {
   288→      const passToken = this.advance();
   289→      return {
   290→        type: 'ExprStatement',
   291→        expression: {
   292→          type: 'Identifier',
   293→          name: 'pass',
   294→          line: passToken.line,
   295→          column: passToken.column,
   296→          mode: passToken.mode,
   297→        },
   298→        line: passToken.line,
   299→        column: passToken.column,
   300→        mode: passToken.mode,
   301→      };
   302→    }
   303→
   304→    // let 또는 식별자 (할당 가능성)
   305→    if (token.type === TokenType.LET || token.type === TokenType.IDENTIFIER) {
   306→      return this.parseAssignOrExpr();
   307→    }
   308→
   309→    // 기본값: 표현식 문장
   310→    const expr = this.parseExpression();
   311→    const startToken = this.peek();
   312→    return {
   313→      type: 'ExprStatement',
   314→      expression: expr,
   315→      line: startToken.line,
   316→      column: startToken.column,
   317→      mode: startToken.mode,
   318→    };
   319→  }
   320→
   321→  /**
   322→   * Return 문장 파싱
   323→   */
   324→  private parseReturnStatement(): AST.ReturnStatement {
   325→    const startToken = this.consume(TokenType.RETURN, 'return 필요');
   326→    let value: AST.Expression | undefined;
   327→
   328→    // 반환값이 있으면 파싱
   329→    if (!this.check(TokenType.NEWLINE) && !this.check(TokenType.DEDENT) && !this.check(TokenType.RBRACE)) {
   330→      value = this.parseExpression();
   331→    }
   332→
   333→    return {
   334→      type: 'Return',
   335→      value,
   336→      line: startToken.line,
   337→      column: startToken.column,
   338→      mode: startToken.mode,
   339→    };
   340→  }
   341→
   342→  /**
   343→   * 할당 또는 표현식 파싱
   344→   */
   345→  private parseAssignOrExpr(): AST.Statement {
   346→    const startToken = this.peek();
   347→
   348→    // let x = value
   349→    if (startToken.type === TokenType.LET) {
   350→      this.advance();
   351→      const nameToken = this.consume(TokenType.IDENTIFIER, '변수명 필요');
   352→      this.consume(TokenType.EQUAL, '= 필요');
   353→      const value = this.parseExpression();
   354→
   355→      return {
   356→        type: 'Assign',
   357→        name: nameToken.value,
   358→        value,
   359→        line: startToken.line,
   360→        column: startToken.column,
   361→        mode: startToken.mode,
   362→      };
   363→    }
   364→
   365→    // x = value 또는 함수호출 등
   366→    if (startToken.type === TokenType.IDENTIFIER) {
   367→      const nameToken = this.peek();
   368→      const name = nameToken.value;
   369→      this.advance();
   370→
   371→      if (this.check(TokenType.EQUAL)) {
   372→        this.advance();
   373→        const value = this.parseExpression();
   374→
   375→        return {
   376→          type: 'Assign',
   377→          name,
   378→          value,
   379→          line: startToken.line,
   380→          column: startToken.column,
   381→          mode: startToken.mode,
   382→        };
   383→      }
   384→
   385→      // 아니면 전체 표현식으로 다시 파싱 (함수호출 등 포함)
   386→      // pos를 한 칸 뒤로 이동하여 식별자부터 다시 파싱
   387→      this.pos--;
   388→      const expr = this.parseExpression();
   389→
   390→      return {
   391→        type: 'ExprStatement',
   392→        expression: expr,
   393→        line: startToken.line,
   394→        column: startToken.column,
   395→        mode: startToken.mode,
   396→      };
   397→    }
   398→
   399→    throw new Error(`예상치 못한 토큰 at line ${startToken.line}`);
   400→  }
   401→
   402→  /**
   403→   * 표현식 파싱
   404→   * 간단한 구현: 곱셈/나눗셈 → 덧셈/뺄셈 → 비교/논리
   405→   */
   406→  private parseExpression(): AST.Expression {
   407→    return this.parseLogicalOr();
   408→  }
   409→
   410→  /**
   411→   * 논리 OR 파싱: ||
   412→   */
   413→  private parseLogicalOr(): AST.Expression {
   414→    let expr = this.parseLogicalAnd();
   415→
   416→    while (this.match(TokenType.OR)) {
   417→      const operator = this.previous().value;
   418→      const right = this.parseLogicalAnd();
   419→      const token = this.previous();
   420→      expr = {
   421→        type: 'BinaryExpr',
   422→        left: expr,
   423→        operator,
   424→        right,
   425→        line: token.line,
   426→        column: token.column,
   427→        mode: token.mode,
   428→      };
   429→    }
   430→
   431→    return expr;
   432→  }
   433→
   434→  /**
   435→   * 논리 AND 파싱: &&
   436→   */
   437→  private parseLogicalAnd(): AST.Expression {
   438→    let expr = this.parseEquality();
   439→
   440→    while (this.match(TokenType.AND)) {
   441→      const operator = this.previous().value;
   442→      const right = this.parseEquality();
   443→      const token = this.previous();
   444→      expr = {
   445→        type: 'BinaryExpr',
   446→        left: expr,
   447→        operator,
   448→        right,
   449→        line: token.line,
   450→        column: token.column,
   451→        mode: token.mode,
   452→      };
   453→    }
   454→
   455→    return expr;
   456→  }
   457→
   458→  /**
   459→   * 등호/부등호 파싱: ==, !=
   460→   */
   461→  private parseEquality(): AST.Expression {
   462→    let expr = this.parseComparison();
   463→
   464→    while (this.match(TokenType.EQ, TokenType.NE)) {
   465→      const operator = this.previous().value;
   466→      const right = this.parseComparison();
   467→      const token = this.previous();
   468→      expr = {
   469→        type: 'BinaryExpr',
   470→        left: expr,
   471→        operator,
   472→        right,
   473→        line: token.line,
   474→        column: token.column,
   475→        mode: token.mode,
   476→      };
   477→    }
   478→
   479→    return expr;
   480→  }
   481→
   482→  /**
   483→   * 비교 파싱: <, >, <=, >=
   484→   */
   485→  private parseComparison(): AST.Expression {
   486→    let expr = this.parseAddition();
   487→
   488→    while (this.match(TokenType.LT, TokenType.GT, TokenType.LE, TokenType.GE)) {
   489→      const operator = this.previous().value;
   490→      const right = this.parseAddition();
   491→      const token = this.previous();
   492→      expr = {
   493→        type: 'BinaryExpr',
   494→        left: expr,
   495→        operator,
   496→        right,
   497→        line: token.line,
   498→        column: token.column,
   499→        mode: token.mode,
   500→      };
   501→    }
   502→
   503→    return expr;
   504→  }
   505→
   506→  /**
   507→   * 덧셈/뺄셈 파싱
   508→   */
   509→  private parseAddition(): AST.Expression {
   510→    let expr = this.parseMultiplication();
   511→
   512→    while (this.match(TokenType.PLUS, TokenType.MINUS)) {
   513→      const operator = this.previous().value;
   514→      const right = this.parseMultiplication();
   515→      const token = this.previous();
   516→      expr = {
   517→        type: 'BinaryExpr',
   518→        left: expr,
   519→        operator,
   520→        right,
   521→        line: token.line,
   522→        column: token.column,
   523→        mode: token.mode,
   524→      };
   525→    }
   526→
   527→    return expr;
   528→  }
   529→
   530→  /**
   531→   * 곱셈/나눗셈 파싱
   532→   */
   533→  private parseMultiplication(): AST.Expression {
   534→    let expr = this.parseUnary();
   535→
   536→    while (this.match(TokenType.STAR, TokenType.SLASH)) {
   537→      const operator = this.previous().value;
   538→      const right = this.parseUnary();
   539→      const token = this.previous();
   540→      expr = {
   541→        type: 'BinaryExpr',
   542→        left: expr,
   543→        operator,
   544→        right,
   545→        line: token.line,
   546→        column: token.column,
   547→        mode: token.mode,
   548→      };
   549→    }
   550→
   551→    return expr;
   552→  }
   553→
   554→  /**
   555→   * 단항 연산 파싱
   556→   */
   557→  private parseUnary(): AST.Expression {
   558→    // TODO: 단항 연산자 (-, !, ~) 처리 가능
   559→    return this.parsePostfix();
   560→  }
   561→
   562→  /**
   563→   * 후위 연산 파싱 (함수 호출, 멤버 접근)
   564→   */
   565→  private parsePostfix(): AST.Expression {
   566→    let expr = this.parsePrimary();
   567→
   568→    while (true) {
   569→      // 함수 호출: foo()
   570→      if (this.match(TokenType.LPAREN)) {
   571→        const args = this.parseArguments();
   572→        this.consume(TokenType.RPAREN, ') 필요');
   573→
   574→        const token = this.previous();
   575→        expr = {
   576→          type: 'Call',
   577→          callee: expr,
   578→          args,
   579→          line: token.line,
   580→          column: token.column,
   581→          mode: token.mode,
   582→        };
   583→      } else {
   584→        break;
   585→      }
   586→    }
   587→
   588→    return expr;
   589→  }
   590→
   591→  /**
   592→   * 기본 표현식 파싱 (리터럴, 식별자 등)
   593→   */
   594→  private parsePrimary(): AST.Expression {
   595→    const token = this.peek();
   596→
   597→    // 숫자
   598→    if (token.type === TokenType.NUMBER) {
   599→      this.advance();
   600→      return {
   601→        type: 'Number',
   602→        value: token.value,
   603→        line: token.line,
   604→        column: token.column,
   605→        mode: token.mode,
   606→      };
   607→    }
   608→
   609→    // 문자열
   610→    if (token.type === TokenType.STRING) {
   611→      this.advance();
   612→      return {
   613→        type: 'String',
   614→        value: token.value,
   615→        line: token.line,
   616→        column: token.column,
   617→        mode: token.mode,
   618→      };
   619→    }
   620→
   621→    // true, false
   622→    if (token.type === TokenType.TRUE || token.type === TokenType.FALSE) {
   623→      this.advance();
   624→      return {
   625→        type: 'Number',
   626→        value: token.type === TokenType.TRUE ? 1 : 0,
   627→        line: token.line,
   628→        column: token.column,
   629→        mode: token.mode,
   630→      };
   631→    }
   632→
   633→    // 식별자
   634→    if (token.type === TokenType.IDENTIFIER) {
   635→      this.advance();
   636→      return {
   637→        type: 'Identifier',
   638→        name: token.value,
   639→        line: token.line,
   640→        column: token.column,
   641→        mode: token.mode,
   642→      };
   643→    }
   644→
   645→    // 괄호 식
   646→    if (this.match(TokenType.LPAREN)) {
   647→      const expr = this.parseExpression();
   648→      this.consume(TokenType.RPAREN, ') 필요');
   649→      return expr;
   650→    }
   651→
   652→    throw new Error(`예상치 못한 토큰: ${token.value} at line ${token.line}`);
   653→  }
   654→
   655→  /**
   656→   * 함수 호출 인자 파싱
   657→   */
   658→  private parseArguments(): AST.Expression[] {
   659→    const args: AST.Expression[] = [];
   660→
   661→    if (!this.check(TokenType.RPAREN)) {
   662→      do {
   663→        args.push(this.parseExpression());
   664→      } while (this.match(TokenType.COMMA));
   665→    }
   666→
   667→    return args;
   668→  }
   669→
   670→  // ========== 헬퍼 메서드 ==========
   671→
   672→  private peek(): Token {
   673→    if (this.pos >= this.tokens.length) {
   674→      return this.tokens[this.tokens.length - 1]; // EOF 토큰
   675→    }
   676→    return this.tokens[this.pos];
   677→  }
   678→
   679→  private advance(): Token {
   680→    if (!this.isAtEnd()) {
   681→      this.pos++;
   682→    }
   683→    return this.previous();
   684→  }
   685→
   686→  private previous(): Token {
   687→    return this.tokens[this.pos - 1];
   688→  }
   689→
   690→  private isAtEnd(): boolean {
   691→    return this.peek().type === TokenType.EOF;
   692→  }
   693→
   694→  private check(type: TokenType): boolean {
   695→    if (this.isAtEnd()) return false;
   696→    return this.peek().type === type;
   697→  }
   698→
   699→  private match(...types: TokenType[]): boolean {
   700→    for (const type of types) {
   701→      if (this.check(type)) {
   702→        this.advance();
   703→        return true;
   704→      }
   705→    }
   706→    return false;
   707→  }
   708→
   709→  private consume(type: TokenType, message: string): Token {
   710→    if (this.check(type)) return this.advance();
   711→
   712→    const token = this.peek();
   713→    throw new Error(`${message} at line ${token.line}, got ${token.value}`);
   714→  }
   715→
   716→  private skipNewlines(): void {
   717→    while (this.match(TokenType.NEWLINE)) {
   718→      // 계속
   719→    }
   720→  }
   721→}
